18	function slugify(filename: string): string {
19	  return filename.replace(/\.md$/i, '');
20	}
21	
22	function normalizeTags(tags: unknown): string[] {
23	  if (Array.isArray(tags)) return tags.map((tag) => String(tag));
24	  if (typeof tags === 'string' && tags.length > 0) return [tags];
25	  return [];
26	}
