28	export function findMarkdownFiles(contentDir: string): string[] {
29	  if (!fs.existsSync(contentDir)) {
30	    throw new Error(`Content directory not found: ${contentDir}`);
31	  }
32	  return fs
33	    .readdirSync(contentDir)
34	    .filter((file) => file.toLowerCase().endsWith('.md'))
35	    .sort();
36	}
