38	export function buildPage(contentDir: string, filename: string): Page {
39	  const filePath = path.join(contentDir, filename);
40	  const raw = fs.readFileSync(filePath, 'utf-8');
41	  const { data, content } = parseFrontmatter(raw);
42	  const body = renderMarkdown(content);
43	  const slug = slugify(filename);
44	  const title = typeof data.title === 'string' && data.title.length > 0 ? data.title : slug;
45	  const date = typeof data.date === 'string' ? data.date : undefined;
46	  const tags = normalizeTags(data.tags);
47	  const outputPath = `${slug}.html`;
48	  const html = renderPageTemplate({ title, date, tags, body });
49	  return { slug, title, date, tags, html, outputPath };
50	}
51	
52	export function build(options: BuildOptions): BuildResult {
53	  const { contentDir, outputDir } = options;
54	  const files = findMarkdownFiles(contentDir);
55	  const pages = files.map((file) => buildPage(contentDir, file));
56	
57	  fs.mkdirSync(outputDir, { recursive: true });
58	  for (const page of pages) {
59	    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
60	  }
61	  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndexTemplate(pages), 'utf-8');
62	
63	  return { pages, outputDir };
64	}
