12	export interface PageTemplateData {
13	  title: string;
14	  date?: string;
15	  tags: string[];
16	  body: string;
17	}
18	
19	export function renderPageTemplate(data: PageTemplateData): string {
20	  const { title, date, tags, body } = data;
21	  const dateHtml = date ? `<p class="date">${escapeHtml(date)}</p>\n` : '';
22	  const tagsHtml = tags.length
23	    ? `<ul class="tags">${tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>\n`
24	    : '';
25	  return `<!DOCTYPE html>
26	<html lang="en">
27	<head>
28	<meta charset="UTF-8">
29	<title>${escapeHtml(title)}</title>
30	</head>
31	<body>
32	<article>
33	<h1>${escapeHtml(title)}</h1>
34	${dateHtml}${tagsHtml}${body}
35	</article>
36	</body>
37	</html>
38	`;
39	}
40	
41	export function renderIndexTemplate(pages: Page[]): string {
42	  const items = pages
43	    .map((page) => {
44	      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
45	      return `<li><a href="${page.outputPath}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
46	    })
47	    .join('\n');
48	  return `<!DOCTYPE html>
49	<html lang="en">
50	<head>
51	<meta charset="UTF-8">
52	<title>Index</title>
53	</head>
54	<body>
55	<h1>All Pages</h1>
56	<ul class="page-list">
57	${items}
58	</ul>
59	</body>
60	</html>
61	`;
62	}
