1	import matter from 'gray-matter';
2	
3	export interface FrontmatterResult {
4	  data: Record<string, unknown>;
5	  content: string;
6	}
7	
8	const FRONTMATTER_BLOCK = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;
9	
10	function parseScalar(raw: string): unknown {
11	  const trimmed = raw.trim();
12	  if (
13	    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
14	    (trimmed.startsWith("'") && trimmed.endsWith("'"))
15	  ) {
16	    return trimmed.slice(1, -1);
17	  }
18	  if (trimmed === 'true') return true;
19	  if (trimmed === 'false') return false;
20	  if (trimmed !== '' && !Number.isNaN(Number(trimmed))) return Number(trimmed);
21	  return trimmed;
22	}
23	
24	function parseValue(key: string, raw: string): unknown {
25	  const trimmed = raw.trim();
26	  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
27	    const inner = trimmed.slice(1, -1).trim();
28	    if (!inner) return [];
29	    return inner.split(',').map((item) => parseScalar(item));
30	  }
31	  if (key === 'tags' && trimmed.includes(',')) {
32	    return trimmed.split(',').map((item) => parseScalar(item));
33	  }
34	  return parseScalar(trimmed);
35	}
36	
37	/**
38	 * Splits a `---`-delimited YAML frontmatter block into key: value pairs.
39	 * Only flat scalar/array values are supported (no nested maps).
40	 */
41	function parseSimpleYaml(block: string): Record<string, unknown> {
42	  const data: Record<string, unknown> = {};
43	  for (const line of block.split(/\r?\n/)) {
44	    const trimmedLine = line.trim();
45	    if (!trimmedLine || trimmedLine.startsWith('#')) continue;
46	    const separatorIndex = trimmedLine.indexOf(':');
47	    if (separatorIndex === -1) continue;
48	    const key = trimmedLine.slice(0, separatorIndex).trim();
49	    const rawValue = trimmedLine.slice(separatorIndex + 1);
50	    if (!key) continue;
51	    data[key] = parseValue(key, rawValue);
52	  }
53	  return data;
54	}
55	
56	/**
57	 * Parses frontmatter from raw Markdown source. gray-matter only understands
58	 * JSON frontmatter here, so the `---`-delimited YAML block is additionally
59	 * parsed by hand and merged over gray-matter's output.
60	 */
61	export function parseFrontmatter(raw: string): FrontmatterResult {
62	  const parsed = matter(raw);
63	  const match = raw.match(FRONTMATTER_BLOCK);
64	  const yamlData = match ? parseSimpleYaml(match[1]) : {};
65	  return {
66	    data: { ...parsed.data, ...yamlData },
67	    content: parsed.content,
68	  };
69	}
